quota_scripts.script:
function httpErr(e) {
  var m = e && e.message ? String(e.message) : String(e);
  if (m.indexOf("HTTP ") === 0) return m;
  if (m.indexOf("JSON parse: ") === 0) return "Parse: " + m.slice(12);
  return "Network: " + m;
}
function num(v) {
  if (typeof v === "number") return v;
  if (typeof v === "string" && v.trim() !== "" && !isNaN(Number(v))) return Number(v);
  return 0.0;
}
function parseNum(v) {
  if (typeof v === "number") return v;
  if (typeof v === "string" && v.trim() !== "" && !isNaN(Number(v))) return Number(v);
  return null;
}
if (ctx.apiKey == null || ctx.apiKey.trim() === "") {
  return { success: false, error: "New API: api_key required for token usage query" };
}
var root = ctx.baseUrl.replace(/\/+$/, "");
var pos = root.lastIndexOf("/");
if (pos >= 0) {
  var last = root.slice(pos + 1);
  if (last.length > 1 && last.charAt(0) === "v" && /^[0-9]+$/.test(last.slice(1))) {
    root = root.slice(0, pos);
  }
}
var usageUrl = root + "/api/usage/token/?key=" + encodeURIComponent(ctx.apiKey) + "&api_key=" + encodeURIComponent(ctx.apiKey);
var step1;
try {
  step1 = http.get(usageUrl, { Authorization: "Bearer " + ctx.apiKey });
} catch (e) {
  return { success: false, error: "Token usage: " + httpErr(e) };
}
if (step1 == null) step1 = {};
var data = step1.data;
if (data === undefined) {
  return { success: false, error: "Token usage: Missing data field" };
}
if (data == null || typeof data !== "object") data = {};
var unlimited = data.unlimited_quota === true;
var totalGranted = num(data.total_granted);
var totalUsed = num(data.total_used);
var totalAvailable = num(data.total_available);
if (!unlimited) {
  var remaining = totalAvailable / 500000.0;
  var used = totalUsed / 500000.0;
  var total = totalGranted / 500000.0;
  return {
    success: true,
    error: null,
    balance: {
      remaining: remaining,
      total: total > 0.0 ? total : null,
      used: used > 0.0 ? used : null,
      currency: "USD",
      is_valid: remaining > 0.0
    },
    coding_plan: null
  };
}
var extra = {};
try { extra = JSON.parse(ctx.extra); } catch (e) { extra = {}; }
if (extra == null || typeof extra !== "object") extra = {};
var n = extra.newapi != null && typeof extra.newapi === "object" ? extra.newapi : {};
var balanceBaseUrl = typeof n.balance_base_url === "string" ? n.balance_base_url : "";
if (balanceBaseUrl === "" && typeof extra.balance_base_url === "string") balanceBaseUrl = extra.balance_base_url;
var balanceApiKey = typeof n.balance_api_key === "string" ? n.balance_api_key : "";
if (balanceApiKey === "" && typeof extra.balance_api_key === "string") balanceApiKey = extra.balance_api_key;
if (balanceApiKey.trim() === "") {
  return { success: false, error: "New API: unlimited token requires balance_api_key in config" };
}
if (balanceBaseUrl === "") {
  return { success: false, error: "New API: unlimited token requires balance_base_url" };
}
var selfBody;
try {
  selfBody = http.get(balanceBaseUrl.replace(/\/+$/, "") + "/api/user/self", { Authorization: "Bearer " + balanceApiKey, "Content-Type": "application/json" });
} catch (e) {
  return { success: false, error: httpErr(e) };
}
if (selfBody == null) selfBody = {};
if (selfBody.success !== true) {
  return { success: false, error: typeof selfBody.message === "string" ? selfBody.message : "Query failed" };
}
var ud = selfBody.data;
if (ud === undefined) {
  return { success: false, error: "Missing data field" };
}
if (ud == null || typeof ud !== "object") ud = {};
var userIdStr = null;
if (typeof ud.id === "number" && isFinite(ud.id)) userIdStr = String(ud.id);
else if (typeof ud.id === "string") userIdStr = ud.id;
var remaining2 = num(ud.quota) / 500000.0;
var used2 = num(ud.used_quota) / 500000.0;
return {
  success: true,
  error: null,
  balance: {
    remaining: remaining2,
    total: remaining2 + used2,
    used: used2,
    currency: "USD",
    is_valid: remaining2 > 0.0
  },
  coding_plan: null,
  newapi_user_id: userIdStr
};
